import type { LanguageCode } from "./i18n";

type LanguageRow = readonly [string, string, string, string, string, string, string];
type Rows = Record<string, LanguageRow>;
const languageIndex: Record<LanguageCode, number> = { en: 0, fr: 1, es: 2, pt: 3, id: 4, vi: 5, zh: 6 };
function selectRows(rows: Rows, language: LanguageCode): Record<string, string> {
  const index = languageIndex[language];
  return Object.fromEntries(Object.entries(rows).map(([key, values]) => [key, values[index] ?? values[0]]));
}

